using System;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PurgingIncenseOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/PurgingIncenseOmenData")]
public class PurgingIncenseOmenData : OnSpecificDiceTierOmenData
{
	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		base.Initialize(omenInstance);
	}

	public override void ActivateOmen(GameObject target = null)
	{
		if (EnableOmenCounter)
		{
			counter++;
			if (counter >= TriggerAmount)
			{
				counter = 0;
				ReferenceSingleton<BattleHandler>.Instance.PurgingIncenseActivated();
				omenInstance.EnqueueOmenFeedbackAndPlay();
				(ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance as DiceInstance).DestroyDiceDisposeAction();
			}
			omenInstance.UpdateOmenCounter();
		}
		else
		{
			ReferenceSingleton<BattleHandler>.Instance.PurgingIncenseActivated();
			(ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance as DiceInstance).DestroyDiceDisposeAction();
		}
	}

	public override Action<Dice> GetOmenAction(OmenInstance omenInstance)
	{
		return delegate(Dice dieToCompare)
		{
			if (dieToCompare.DiceTier == diceTier)
			{
				bool flag = false;
				if (ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance != null && ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance.ActionFace.BattleAction is PurgeAction)
				{
					flag = true;
				}
				if (EnableOmenCounter)
				{
					if (OmenTriggered())
					{
						if (!flag)
						{
							omenInstance.EnqueueOmenFeedbackAndPlay();
							omenInstance.StopBlinkingFeedback();
							ActivateOmen();
						}
					}
					else if (OmenAboutToTrigger())
					{
						omenInstance.PlayBlinkingFeedback();
						ActivateOmen();
					}
				}
				else if (!flag)
				{
					ActivateOmen();
				}
			}
		};
	}

	protected override string GetFirstPartAfterDicerTierPlayerLocalizedDescription()
	{
		return GetOmenRawLocalizedDescription();
	}
}
